// @ai:generated by=claude-opus-4-6 date=2026-02-27
package migrate

import (
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// ChangeType 描述變更類型
type ChangeType int

const (
	AddTable        ChangeType = iota // 新增表
	DropTable                         // 刪除表
	AddColumn                         // 新增欄位
	DropColumn                        // 刪除欄位
	AlterColumn                       // 修改欄位（型別、NOT NULL、DEFAULT、自動遞增）
	RenameTable                       // 表更名（migrate:"renamed_from=..."）
	RenameColumn                      // 欄位更名（migrate:"renamed_from=..."）
	AddUnique                         // 新增 UNIQUE 約束
	DropUnique                        // 移除 UNIQUE 約束
	AlterPrimaryKey                   // 主鍵欄位變更（不支援自動產生 SQL）
)

// Change 描述單一 schema 變更
type Change struct {
	Type          ChangeType    `json:"type"`
	Table         string        `json:"table"`
	OldTable      string        `json:"old_table,omitempty"` // RenameTable 的舊表名
	Column        *ColumnSchema `json:"column,omitempty"`
	OldCol        *ColumnSchema `json:"old_column,omitempty"` // AlterColumn / RenameColumn 的舊欄位
	Schema        *TableSchema  `json:"schema,omitempty"`     // AddTable：新表；DropTable / RenameTable：快照中的舊表
	Unique        *UniqueSchema `json:"unique,omitempty"`     // AddUnique / DropUnique
	PrimaryKey    []string      `json:"primary_key,omitempty"`
	OldPrimaryKey []string      `json:"old_primary_key,omitempty"`
}

// String 回傳變更的可讀描述
func (c Change) String() string {
	switch c.Type {
	case AddTable:
		return "ADD TABLE " + c.Table
	case DropTable:
		return "DROP TABLE " + c.Table
	case AddColumn:
		if c.Column != nil {
			return "ADD COLUMN " + c.Table + "." + c.Column.Name
		}
		return "ADD COLUMN " + c.Table
	case DropColumn:
		if c.Column != nil {
			return "DROP COLUMN " + c.Table + "." + c.Column.Name
		}
		return "DROP COLUMN " + c.Table
	case AlterColumn:
		if c.Column != nil {
			return "ALTER COLUMN " + c.Table + "." + c.Column.Name
		}
		return "ALTER COLUMN " + c.Table
	case RenameTable:
		return "RENAME TABLE " + c.OldTable + " -> " + c.Table
	case RenameColumn:
		if c.Column != nil && c.OldCol != nil {
			return "RENAME COLUMN " + c.Table + "." + c.OldCol.Name + " -> " + c.Column.Name
		}
		return "RENAME COLUMN " + c.Table
	case AddUnique, DropUnique:
		op := "ADD UNIQUE "
		if c.Type == DropUnique {
			op = "DROP UNIQUE "
		}
		if c.Unique != nil {
			return op + c.Table + " (" + strings.Join(c.Unique.Columns, ", ") + ")"
		}
		return op + c.Table
	case AlterPrimaryKey:
		return "ALTER PRIMARY KEY " + c.Table + " (" + strings.Join(c.OldPrimaryKey, ", ") +
			") -> (" + strings.Join(c.PrimaryKey, ", ") + ")"
	default:
		return "UNKNOWN"
	}
}

// Diff 比對當前 schema 與快照，產生 ChangeSet（順序固定：依 current 的順序處理各表，
// 刪除的表依名稱排序放最後——先前依 map 走訪，順序每次不同）。
// 帶 migrate:"renamed_from=..." 提示的表 / 欄位，若舊名稱存在於快照且新名稱不存在，產生 Rename 而非 Drop + Add
func Diff(current []TableSchema, snapshot *Snapshot) []Change {
	var changes []Change

	currentNames := make(map[string]bool, len(current))
	for _, t := range current {
		currentNames[t.Name] = true
	}
	matched := make(map[string]bool)

	for _, table := range current {
		if old, ok := snapshot.Tables[table.Name]; ok {
			matched[table.Name] = true
			changes = append(changes, diffTable(table.Name, old, table)...)
			continue
		}
		if from := table.RenamedFrom; from != "" && !currentNames[from] && !matched[from] {
			if old, ok := snapshot.Tables[from]; ok {
				matched[from] = true
				o := old
				changes = append(changes, Change{Type: RenameTable, Table: table.Name, OldTable: from, Schema: &o})
				changes = append(changes, diffTable(table.Name, old, table)...)
				continue
			}
		}
		t := table
		changes = append(changes, Change{Type: AddTable, Table: table.Name, Schema: &t})
	}

	dropped := make([]string, 0)
	for name := range snapshot.Tables {
		if !currentNames[name] && !matched[name] {
			dropped = append(dropped, name)
		}
	}
	sort.Strings(dropped)
	for _, name := range dropped {
		old := snapshot.Tables[name]
		changes = append(changes, Change{Type: DropTable, Table: name, Schema: &old})
	}

	return changes
}

// diffTable 比對同一張表的新舊定義：更名、新增、修改、UNIQUE、刪除、主鍵
func diffTable(table string, old, cur TableSchema) []Change {
	oldMap := make(map[string]ColumnSchema, len(old.Columns))
	for _, c := range old.Columns {
		oldMap[c.Name] = c
	}
	newNames := make(map[string]bool, len(cur.Columns))
	for _, c := range cur.Columns {
		newNames[c.Name] = true
	}

	var renames, adds, alters, drops []Change
	matched := make(map[string]bool)
	renamed := make(map[string]string) // 舊欄位名 → 新欄位名

	for _, col := range cur.Columns {
		c := col
		if o, ok := oldMap[col.Name]; ok {
			matched[col.Name] = true
			if columnChanged(o, col) {
				alters = append(alters, Change{Type: AlterColumn, Table: table, Column: &c, OldCol: &o})
			}
			continue
		}
		if from := col.RenamedFrom; from != "" && !newNames[from] && !matched[from] {
			if o, ok := oldMap[from]; ok {
				matched[from] = true
				renamed[from] = col.Name
				oc := o
				renames = append(renames, Change{Type: RenameColumn, Table: table, Column: &c, OldCol: &oc})
				if columnChanged(o, col) {
					o.Name = col.Name // 更名後以新名稱修改定義
					alters = append(alters, Change{Type: AlterColumn, Table: table, Column: &c, OldCol: &o})
				}
				continue
			}
		}
		adds = append(adds, Change{Type: AddColumn, Table: table, Column: &c})
	}
	for _, col := range old.Columns {
		if !matched[col.Name] {
			c := col
			drops = append(drops, Change{Type: DropColumn, Table: table, Column: &c})
		}
	}

	// UNIQUE：舊約束的欄位名先套用更名再比對（更名時約束跟著欄位走）
	translate := func(cols []string) []string {
		out := make([]string, len(cols))
		for i, c := range cols {
			if n, ok := renamed[c]; ok {
				c = n
			}
			out[i] = c
		}
		return out
	}
	key := func(u UniqueSchema) string { return u.Name + "\x00" + strings.Join(u.Columns, "\x00") }
	oldUniques := make(map[string]bool)
	for _, u := range old.Uniques {
		oldUniques[key(UniqueSchema{Name: u.Name, Columns: translate(u.Columns)})] = true
	}
	newUniques := make(map[string]bool)
	for _, u := range cur.Uniques {
		newUniques[key(u)] = true
	}
	var uniqueChanges []Change
	for _, u := range old.Uniques {
		tu := UniqueSchema{Name: u.Name, Columns: translate(u.Columns)}
		if !newUniques[key(tu)] {
			uniqueChanges = append(uniqueChanges, Change{Type: DropUnique, Table: table, Unique: &tu})
		}
	}
	for _, u := range cur.Uniques {
		if !oldUniques[key(u)] {
			nu := u
			uniqueChanges = append(uniqueChanges, Change{Type: AddUnique, Table: table, Unique: &nu})
		}
	}

	var changes []Change
	if oldPK := translate(old.PrimaryKey); strings.Join(oldPK, "\x00") != strings.Join(cur.PrimaryKey, "\x00") {
		changes = append(changes, Change{Type: AlterPrimaryKey, Table: table,
			PrimaryKey: cur.PrimaryKey, OldPrimaryKey: old.PrimaryKey})
	}
	changes = append(changes, renames...)
	changes = append(changes, adds...)
	changes = append(changes, alters...)
	changes = append(changes, uniqueChanges...)
	changes = append(changes, drops...)
	return changes
}

// columnChanged 判斷欄位定義是否有會影響 DDL 的變更。
// Go 型別不比對（先前 int32 → int 等對應到同一 SQL 型別的變更也產生空的 ALTER）；
// 主鍵與 UNIQUE 由 diffTable 以表層級比對
func columnChanged(old, new ColumnSchema) bool {
	return !strings.EqualFold(old.SQLType, new.SQLType) ||
		old.NotNull != new.NotNull ||
		old.Default != new.Default ||
		old.AutoIncrement != new.AutoIncrement ||
		old.Identity != new.Identity
}

// Destructive 回傳此變更可能遺失資料或在既有資料上失敗的原因；安全的變更回傳空字串。
// hyp migrate diff 遇到此類變更時，未加 --allow-destructive 即失敗
func (c Change) Destructive() string {
	switch c.Type {
	case DropTable:
		return fmt.Sprintf("drops table %s and all of its data", c.Table)
	case DropColumn:
		return fmt.Sprintf("drops column %s.%s and its data", c.Table, c.Column.Name)
	case AlterColumn:
		if c.OldCol != nil && !typeWidens(c.OldCol.SQLType, c.Column.SQLType) {
			return fmt.Sprintf("changes the type of %s.%s from %s to %s (existing values may be truncated or fail to convert)",
				c.Table, c.Column.Name, c.OldCol.SQLType, c.Column.SQLType)
		}
	case AddColumn:
		col := c.Column
		if col.NotNull && col.Default == "" && !col.AutoIncrement && !col.Identity {
			return fmt.Sprintf("adds NOT NULL column %s.%s without a DEFAULT to an existing table "+
				"(fails on PostgreSQL when the table has rows; MySQL fills in zero values)", c.Table, col.Name)
		}
	}
	return ""
}

var (
	spaceRe   = regexp.MustCompile(`\s+`)
	varcharRe = regexp.MustCompile(`^(?:VARCHAR|CHARACTER VARYING)(?:\((\d+)\))?$`)
)

// intRank 整數型別的寬度等級；0 表示非整數
func intRank(t string) int {
	switch t {
	case "TINYINT":
		return 1
	case "SMALLINT", "INT2", "SMALLSERIAL":
		return 2
	case "MEDIUMINT":
		return 3
	case "INTEGER", "INT", "INT4", "SERIAL":
		return 4
	case "BIGINT", "INT8", "BIGSERIAL":
		return 5
	}
	return 0
}

// textRank 文字型別可容納的長度（-1 表示無上限 / 非常大）；0 表示非文字型別
func textRank(t string) int {
	if m := varcharRe.FindStringSubmatch(t); m != nil {
		if m[1] == "" {
			return -1 // PostgreSQL 不帶長度的 VARCHAR 等同 TEXT
		}
		n, _ := strconv.Atoi(m[1])
		return n
	}
	switch t {
	case "TEXT", "MEDIUMTEXT", "LONGTEXT":
		return -1
	}
	return 0
}

// typeWidens 判斷 old → new 是否為不會遺失資料的型別變更（相同、整數 / 浮點加寬、文字加長）
func typeWidens(old, new string) bool {
	o := spaceRe.ReplaceAllString(strings.ToUpper(strings.TrimSpace(old)), " ")
	n := spaceRe.ReplaceAllString(strings.ToUpper(strings.TrimSpace(new)), " ")
	if o == n {
		return true
	}
	if ro, rn := intRank(o), intRank(n); ro > 0 && rn > 0 {
		return rn >= ro
	}
	isReal := func(t string) bool { return t == "REAL" || t == "FLOAT4" || t == "FLOAT" }
	isDouble := func(t string) bool { return t == "DOUBLE PRECISION" || t == "DOUBLE" || t == "FLOAT8" }
	if (isReal(o) || isDouble(o)) && isDouble(n) {
		return true
	}
	if to, tn := textRank(o), textRank(n); to != 0 && tn != 0 {
		return tn == -1 || (to != -1 && tn >= to)
	}
	return false
}

// RenameHints 為同一張表中「刪除一欄、新增一欄且型別相同」與「刪除一張表、新增一張表」的情況
// 產生提示：若其實是更名，應加上 migrate:"renamed_from=..." tag，否則會被當成 DROP + ADD（資料遺失）
func RenameHints(changes []Change) []string {
	var hints []string
	var addedTables, droppedTables []string
	for _, c := range changes {
		switch c.Type {
		case AddTable:
			addedTables = append(addedTables, c.Table)
		case DropTable:
			droppedTables = append(droppedTables, c.Table)
		case DropColumn:
			for _, a := range changes {
				if a.Type == AddColumn && a.Table == c.Table && strings.EqualFold(a.Column.SQLType, c.Column.SQLType) {
					hints = append(hints, fmt.Sprintf(
						"%s: column %q is dropped and %q is added with the same type %s; if it was renamed, tag the field `migrate:\"renamed_from=%s\"`",
						c.Table, c.Column.Name, a.Column.Name, a.Column.SQLType, c.Column.Name))
				}
			}
		}
	}
	for _, d := range droppedTables {
		for _, a := range addedTables {
			hints = append(hints, fmt.Sprintf(
				"table %q is dropped and %q is added; if it was renamed, tag its bun.BaseModel field `migrate:\"renamed_from=%s\"`",
				d, a, d))
		}
	}
	return hints
}
